  /* legacy buttons / tags */
  .normal_button, .text_button, .quinary_button, .tag,
  .square_button, .full_width_button {
    background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .normal_button:hover, .text_button:hover, .square_button:hover, .full_width_button:hover { background-color: #2d333b !important; }
  .tag:hover { background-color: #2d333b !important; }
  .square_button *, .full_width_button * { color: #e6edf3 !important; }
  /* the neutral ".square_button" surface ties on specificity and comes first, so it swallows
     every brand fill; re-assert each with a two-class selector. Instagram/Apple are brand-black
     and need a visible edge. */
  .square_button.square_button--facebook { background-color: #3b5998 !important; border-color: #3b5998 !important; }
  .square_button.square_button--twitter { background-color: #55acee !important; border-color: #55acee !important; }
  .square_button.square_button--google { background-color: #dd4b39 !important; border-color: #dd4b39 !important; }
  .square_button.square_button--spotify { background-color: #2ebd59 !important; border-color: #2ebd59 !important; }
  .square_button.square_button--email { background-color: #9a9a9a !important; border-color: #9a9a9a !important; }
  .square_button.square_button--instagram,
  .square_button.square_button--apple { background-color: #000000 !important; border-color: #2d333b !important; }
  /* each brand fill above ties with, and follows, the neutral ".square_button:hover", so
     every variant needs its own. Genius lightens by 20%. */
  .square_button.square_button--facebook:hover { background-color: #4c70ba !important; border-color: #4c70ba !important; }
  .square_button.square_button--twitter:hover { background-color: #83c3f3 !important; border-color: #83c3f3 !important; }
  .square_button.square_button--google:hover { background-color: #e47265 !important; border-color: #e47265 !important; }
  .square_button.square_button--instagram:hover { background-color: #4d4d4d !important; }
  .square_button.square_button--apple:hover { background-color: #1a1a1a !important; }
  .square_button.square_button--email:hover { background-color: #b4b4b4 !important; border-color: #b4b4b4 !important; }
  /* genius's opt-out of the family chrome, carried by the vote thumbs, their total and the
     comment/share actions. The neutral surface is one class less specific but its fill and edge
     still land. */
  .square_button.square_button--transparent {
    background-color: transparent !important; border-color: transparent !important; }
  .square_button.square_button--transparent:hover { background-color: #2d333b !important; }
  .square_button--facebook, .square_button--twitter, .square_button--google,
  .square_button--instagram, .square_button--spotify, .square_button--apple, .square_button--email {
    color: #ffffff !important; }
  /* an accent icon button; the neutral .square_button rule flattens its periwinkle glyph */
  .square_button.square_button--purple,
  .square_button.square_button--purple * { color: #9aa7f0 !important; fill: #9aa7f0 !important; }
  /* the rest of the family is an OUTLINE control, not a fill family: bagon puts the whole
     meaning in one hue on border-color + color + .inline_icon fill. The neutral surface rule ties
     and comes first, so every variant collapses into one grey box. Lifted for 4.5:1 on the
     #21262d fill. */
  .square_button.square_button--red, .square_button.square_button--red *,
  .square_button.square_button--red .inline_icon {
    color: #ff4d4d !important; fill: #ff4d4d !important; border-color: #ff4d4d !important; }
  .square_button.square_button--green, .square_button.square_button--green *,
  .square_button.square_button--green .inline_icon {
    color: #0ecb27 !important; fill: #0ecb27 !important; border-color: #0ecb27 !important; }
  .square_button.square_button--yellow, .square_button.square_button--yellow *,
  .square_button.square_button--yellow .inline_icon {
    color: #ffff64 !important; fill: #ffff64 !important; border-color: #ffff64 !important; }
  .square_button.square_button--white, .square_button.square_button--white *,
  .square_button.square_button--white .inline_icon {
    color: #ffffff !important; fill: #ffffff !important; border-color: #ffffff !important; }
  /* the DE-emphasised end of the family: only label and glyph move. Pinning their edge to
     #9a9a9a too would make the muted variant louder than the default #2d333b edge. "--disabled"
     has no cue but that hue. */
  .square_button.square_button--gray, .square_button.square_button--gray *,
  .square_button.square_button--gray .inline_icon,
  .square_button.square_button--waiting, .square_button.square_button--waiting *,
  .square_button.square_button--waiting .inline_icon,
  .square_button.square_button--disabled, .square_button.square_button--disabled *,
  .square_button.square_button--disabled .inline_icon {
    color: #9a9a9a !important; fill: #9a9a9a !important; }
  /* the outline form of the two brand buttons: no fill, brand hue on label and glyph, and
     the neutral family rule ties with it and comes first. Facebook blue lifted from #3b5998
     (2.2:1 on #21262d). */
  .square_button.square_button--facebook_inverse,
  .square_button.square_button--facebook_inverse *,
  .square_button.square_button--facebook_inverse .inline_icon {
