  .placeholder .user_badge-iq, .placeholder .user_badge-login {
    background-color: #2d333b !important; color: #2d333b !important; }

  /* periwinkle count chips: keep accent bg, dark label for contrast */
  .profile_contributions_group-count, .profile_contributions_group-count * { color: #14181d !important; }

  /* a solid #99a7ee slab whose white copy the shared typography drops under 1.6:1. Take the
     CSS-triangle tail with it - a ::before whose bottom border carries the plate colour, out of
     reach of "*". */
  .note_bubble { background-color: #2a3050 !important; color: #e6edf3 !important; }
  .note_bubble::before { border-bottom-color: #2a3050 !important; }
  /* genius plates every <del> / <ins> AND its children ("del>*", "ins>*") with background
     !important, so the children must be named or its own child rule keeps them light.
     img.ins / img.del 3px borders carry the same cue. */
  body del, body del > * {
    background-color: #4a1e1e !important; color: #ffb3b3 !important; }
