    background-color: #1b3a1e !important; color: #b3ffb3 !important; }
  .rich_text_formatting img.del { border-color: #f85149 !important; }
  .rich_text_formatting img.ins { border-color: #3fb950 !important; }

  /* green when net-positive, red when negative - a real sentiment cue, flattened by the
     neutral .square_button colour rule above */
  .voting-total--positive, .voting-total--positive * { color: #3fb950 !important; }
  .voting-total--negative, .voting-total--negative * { color: #f85149 !important; }

  /* legacy active header tab: yellow underline -> brand red */
  .header-primary.active, .header_with_login .active {
    background-color: transparent !important; box-shadow: inset 0 -3px 0 #ed4337 !important; }

  /* legacy avatar / image placeholders */
  .user_avatar, .profile_header-avatar, .avatar { background-color: #1c2128 !important; }

  /* legacy "STATS" panel (charts / profile contributor pane): white card with black
     glyph icons + #666 labels -> dark card, light icons, legible labels */
  .statistics_panel { background-color: #1c2128 !important; border-color: #2d333b !important; }
  .statistics_panel svg, .statistics_panel svg path { fill: #c4cdd6 !important; }
  .statistic_and_label-number { color: #e6edf3 !important; }
  .statistic_and_label-subtext { color: #8b949e !important; }

  /* legacy dropdowns / menus */
  .dropdown_menu, .dropdown_menu-item, .menu {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .dropdown_menu-item:hover { background-color: #2d333b !important; }
  /* a white .tooltip panel with black <div> rows - the shared typography list covers inline
     tags only */
  .tooltip { background-color: #1c2128 !important; border-color: #2d333b !important; }
  .tooltip-list_item, .tooltip-list_item * { color: #e6edf3 !important; }
  .tooltip-list_item:hover { background-color: #2d333b !important; }
  /* legacy feed_dropdown paints #f7f7f7 behind the result rows */
  .feed_dropdown, .feed_dropdown--medium_width {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .feed_dropdown .section_header, .feed_dropdown-section_header,
  .feed_dropdown .text_label { color: #8b949e !important; }

  /* every variant paints the chip TWICE: a background-color AND a matching pair of 0.01em
     left/right box-shadows past the inline box, which a background-only override leaves as
     bright slivers. ".referent--yellow" restates its own shadow below. */
  .referent, a.referent {
    background-color: #1c2128 !important; color: #e6edf3 !important; box-shadow: none !important; }
  /* genius keeps an annotation's state entirely in the background-color the base rule above
     repaints, so it has to come back or every annotation looks alike. Re-tint rather than draw
     an inset bar: ".referent" is display:inline with `padding:.2em 0` - no horizontal padding,
     so an inset edge lands on the first glyph. ".referent--yellow" is deliberately absent: bagon
     ships no bare "--yellow" fill, only "--yellow.--highlighted", so at rest it IS the base
     chip. */
  .referent.referent--green { background-color: #1b2a1e !important; }
  .referent.referent--red { background-color: #2e1c1f !important; }
  .referent.referent--highlighted { background-color: #3d3d1a !important; }
  .referent.referent--red.referent--highlighted { background-color: #4a1e1e !important; }
  /* the same three states as a full-bleed panel, plus a scroll-fade ::before ramping to the
     same colour */
  .referent_container--inverse, .referent_container--green {
    background-color: #3d3d1a !important; }
  .referent_container--red { background-color: #4a1e1e !important; }
  .referent_container--inverse .referent_container-excerpt_container::before,
  .referent_container--green .referent_container-excerpt_container::before {
    background-image: linear-gradient(rgba(61, 61, 26, 0), #3d3d1a 85%) !important; }
  .referent_container--red .referent_container-excerpt_container::before {
    background-image: linear-gradient(rgba(74, 30, 30, 0), #4a1e1e 85%) !important; }
  /* a rotated ::before square, white with #e9e9e9 top+left borders - the only two the
     rotation leaves visible, and `*` cannot reach them */
  .standalone_annotation { background-color: #1c2128 !important; }
  /* a light #e9e9e9 card under the dark overlay. "--no_background" is a transparent
     pass-through and "--dark_background" is already #111 - both must stay. */
  .modal_window-content, .modal_window-content-media,
  .modal_window-content--white_background { background-color: #1c2128 !important; }
  .modal_window-content--no_background { background-color: transparent !important; }
  .modal_window-content--dark_background { background-color: #14181d !important; }
  /* pink ink, faint pink candy stripe, pink dotted toggle underline, all greyed by the span
     rule and the blanket border reset */
  .dashed_background_message, .dashed_background_message *,
  .dashed_background_message-underlined_word { color: #ff3d7f !important; }
  .dashed_background_message-underlined_word { border-bottom-color: #ff3d7f !important; }
  .standalone_annotation-referent_fragment--with_caret::before,
  .standalone_annotation-referent_fragment::before {
    background-color: #1c2128 !important; border-color: #2d333b !important; }

  /* MOBILE-ONLY surfaces (legacy "snarly" mobile + the AMP bundle). Genius serves layout by
     USER-AGENT - song page React, artist page snarly, album/article AMP - none reachable by
     narrowing a desktop viewport. */

  /* the panel ships white around already-dark cards. ".slide_over_pane" is the transparent
     backdrop; only the scrollable panel is a surface. */
  .slide_over_pane-scrollable { background-color: #14181d !important; }

  /* brand-yellow bar with a black inline-SVG wordmark (a separate class from the React one)
     and a "SIGN UP" link our link rule lifts to ~1.9:1 on it */
  .page_header-header {
    background-color: #0d1117 !important; border-bottom: 2px solid #ed4337 !important; }
  .page_header-logo svg, .page_header-logo svg path {
    fill: #e6edf3 !important; color: #e6edf3 !important; }
  /* a same-origin amp-iframe (genius.com/amp_iframe_html/search.html), so
     domain("genius.com") matches inside it. The magnifier sits position:absolute BEHIND the
     natively transparent input, so the shared `input` surface rule would bury it - keep the
     field bare, its 2px underline is the affordance. */
  .search_form-text_input { background-color: transparent !important; }
  /* focus MUST re-fill the field opaquely (genius uses #ffff64): that fill is what hides the
     magnifier behind the input, or the query text renders over the glyph */
  .search_form-text_input:focus, .search_form-text_input:valid {
    background-color: #21262d !important; border-bottom-color: #ed4337 !important; }
  .search_form-icon, .search_form-icon path {
    fill: #c4cdd6 !important; color: #c4cdd6 !important; }
  /* a full-width white header between two dark sections */
  .footer_accordion-header_with_arrow { background-color: #14181d !important; }
  /* a second white panel holding the whole answer / translation list; it must take the
     header's tone or the section reads as a slab hanging off a dark bar */
  .footer_accordion-body { background-color: #14181d !important; }
  /* the art stage is already black, but the annotation under it is a separate #f7f7f7
     sheet */
  .cover_art_annotation-content { background-color: #14181d !important; }
  /* chrome #e9e9e9, text pane white. The desktop twin is transparent over an already-dark
     PageGrid, hence the -mobile scope. */
  [class*="LyricsEdit-mobile__Container"],
  [class*="LyricsEdit-mobile__Header"],
  [class*="LyricsEdit-mobile__Controls"] { background-color: #14181d !important; }
  [class*="LyricsEdit-mobile__LyricsContainer"] { background-color: #1c2128 !important; }
  /* the whole preview paragraph is a bare <a> (an AMP tap action) with the affordance only
     on "-read_more", so the shared link rule reaches the body. */
  .album_description_preview a { color: #c4cdd6 !important; }
  .album_description_preview-read_more { color: #9aa7f0 !important; }
  /* genius ships ONE ".checky path" black-fill rule for both bundles, but AMP draws the
     badge as two paths (green square + white tick) where desktop has a tick on a yellow
     <circle>. The desktop tick keys on "#000". */
  .checky path[fill="#27F145"] { fill: #27f145 !important; }
  .checky path[fill="#FFF"] { fill: #ffffff !important; }
  /* the framework's own wrapper is white, banding a 320px creative. The close button is a
     white disc with a grey glyph baked into a data-URI SVG we cannot recolour. */
  amp-sticky-ad, amp-sticky-ad-top-padding { background-color: #14181d !important; }
  .amp-sticky-ad-close-button { filter: invert(1) !important; }
  /* <amp-consent> is itself AMP's full-screen dimmer, rgba(255,255,255,.7): the wash is the
     alpha, not a light surface, so the blanket dark rules miss it. The prompt panel is a CHILD
     and still paints on top. */
  amp-consent, amp-consent#consent_element {
    background-color: rgba(0, 0, 0, 0.7) !important; }

  /* livingtracklist.genius.com - in scope because domain() covers every subdomain. Its only
     stable hooks are CSS-module prefixes ("<Component>-module__<hash>__<part>": the hash rots,
     the name does not), and its paper is one fixed full-viewport "Loader" section the base
     html/body rule never reaches. */
  [class*="Loader-module__"] { background-color: #14181d !important; }
  /* the one string the loader paints brand green; the shared span rule greys it */
  [class*="Loader-module__"][class*="__progress"] span { color: #01a74a !important; }
  /* the pill CTAs carry their label in ink their brand fill was chosen for. Both are <a>,
     and the link rule's :hover half outranks a plain [class*=], so Sweepstakes must name the
     state to hold its label. */
  [class*="MainButton-module__"], [class*="MainButton-module__"] *,
  [class*="ExploreMoreButton-module__"], [class*="ExploreMoreButton-module__"] * {
    color: #14181d !important; }
  [class*="SweepstakesButton-module__"], [class*="SweepstakesButton-module__"] *,
  [class*="SweepstakesButton-module__"]:hover, [class*="SweepstakesButton-module__"]:hover *,
  [class*="SweepstakesButton-module__"]:focus, [class*="SweepstakesButton-module__"]:focus * {
    color: #ffffff !important; }
  /* hover/focus flips the fill yellow -> brand green and the label white; the rest-state
     rule above is !important, so without this the label stays dark on green. */
  [class*="MainButton-module__"]:hover, [class*="MainButton-module__"]:hover *,
  [class*="MainButton-module__"]:focus, [class*="MainButton-module__"]:focus * {
    color: #ffffff !important; }
  /* current decade brand green, the rest black-20%, black on hover - lifting them alike
     erases both cues. The green rule also names :first-child and must stay last: the active item
     carries "__item" too. */
  [class*="TrackExplorerNav-module__"][class*="__item"],
  [class*="TrackExplorerNav-module__"][class*="__item"] * { color: #c4cdd6 !important; }
  [class*="TrackExplorerNav-module__"][class*="__item"]:hover,
  [class*="TrackExplorerNav-module__"][class*="__item"]:hover * { color: #ffffff !important; }
  [class*="TrackExplorerNav-module__"][class*="__active"],
  [class*="TrackExplorerNav-module__"][class*="__active"] *,
  [class*="TrackExplorerNav-module__"][class*="__item"]:first-child,
  [class*="TrackExplorerNav-module__"][class*="__item"]:first-child * { color: #01a74a !important; }
  /* one fixed full-viewport "PageOverlay" whose paper is white - a second sheet the Loader
     rule above never reaches */
  [class*="PageOverlay-module__"] { background-color: #14181d !important; }
  /* a <canvas> masked by loader-mask.svg: the mask cuts the glyphs, the element's own
     background-color is the UNFILLED ink, and the bitmap paints only the green fill over it. */
  canvas[class*="LoaderLogo-module__"] { background-color: #e6edf3 !important; }
  /* solid brand-green plates the site pairs with white copy; the shared p/span/a rules dull
     that to ~2:1 */
  [class*="ExploreVideoInfo-module__"], [class*="ExploreVideoInfo-module__"] *,
  [class*="ExplorePanelists-module__"], [class*="ExplorePanelists-module__"] * {
    color: #ffffff !important; }
  /* both routes separate their sections with full-width #ffff64 plates; the shared
     "ExploreMore" rail gets the same fill as a green -> #ffff64 gradient on /explore. */
  [class*="TrackInsights-module__"][class*="__TrackInsights"],
  [class*="TrackRelated-module__"][class*="__TrackRelated"],
  [class*="ExploreMore-module__"][class*="__ExploreMore"] {
    background-color: #1c2128 !important; }
  [class*="ExploreMore-module__"][class*="__gradient"] {
    background-image: linear-gradient(#01a74a 0px, #1c2128 35%, #1c2128 100%) !important; }
  /* ...except the key-lyric marker, where that yellow IS the signal: keep the fill and put
     its ink back. */
  [class*="TrackLyric-module__"] blockquote span,
  [class*="TrackLyric-module__"] blockquote span * { color: #14181d !important; }
  /* a white "more below" ::after fade and an "Expand" pill keeping the site's white fill and
     the black ink it was chosen for */
  [class*="TrackLyric-module__"][class*="__lyric"]::after {
    background-image: linear-gradient(rgba(20, 24, 29, 0), #14181d) !important; }
  [class*="ExpandButton-module__"], [class*="ExpandButton-module__"] * { color: #14181d !important; }
  /* the wordmark SVG carries no fill attribute and falls back to black; the insight tabs'
     icons take currentColor off a button the shared rules leave black */
  svg[class*="TrackInsights-module__"] path { fill: #c4cdd6 !important; }
  [class*="TrackInsights-module__"] nav button { color: #c4cdd6 !important; }
  /* the current tab is marked ONLY by an opaque border while the rest ship theirs
     transparent */
  [class*="TrackInsights-module__"] nav button { border-color: transparent !important; }
  [class*="TrackInsights-module__"] nav button[aria-current="true"] {
    border-color: #c4cdd6 !important; }
  /* the lockup is one inline SVG of fill="#000" paths. Key to its own class, not every path
     in the footer: the sticky Home pill's chevron is stroked fill="none". */
  svg[class*="Footer-module__"] path { fill: #c4cdd6 !important; }
  /* a bare 24px anchor for the floating Home/Explore pill, natively transparent so the page
     scrolls under it; the shared footer rule would fill it opaque */
  footer[class*="StickyFooter-module__"] { background-color: transparent !important; }

  /* promote.genius.com - the Shopify storefront, in scope through domain(). Its own theme is
     already near-black, so only the two places it paints white need us. */
  /* sits on genius's own yellow plate and carries the ink that plate was chosen for. The H1
     beside it is a BLACK box and must keep the lifted ink. */
  .banner__text.subtitle, .banner__text.subtitle * { color: #14181d !important; }
  /* one WHITE pill with near-black ink, in both element forms, with or without "--primary",
     its label sometimes in a nested <span> */
  a.button, a.button *, button.button, button.button *,
  .shopify-challenge__button, .shopify-challenge__button *,
  .customer button, .customer button * { color: #212121 !important; }
  /* ...except the outline variants, which Dawn fills TRANSPARENT: they sit on the store's
     own near-black panels and take a light label. */
  a.button--secondary, a.button--secondary *,
  a.button--tertiary, a.button--tertiary * { color: #9aa7f0 !important; }
  button.button--secondary, button.button--secondary *,
  button.button--tertiary, button.button--tertiary * { color: #e6edf3 !important; }
  /* a WHITE disc with near-black ink inside the cart <a>, so the shared link rule repaints
     its count */
  .cart-count-bubble, .cart-count-bubble * { color: #212121 !important; }
  /* a Booster widget in an about:blank subframe inheriting the store's origin, so this block
     applies inside it */
  .ba_widget_main_design { background-color: #1c2128 !important; }
  .ba_initial_state_body { color: #c4cdd6 !important; }

  /* Forms / inputs (shared) */
  input, textarea, select {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  input::placeholder, textarea::placeholder { color: #8b949e !important; }
  /* react-select hides a content-sized <input> in a transparent div, so the surface above
     chips the typed text instead of filling the field. Emotion names the control
     "css-<hash>-control"; genius's own components are styled-components, so that prefix reaches
     react-select alone. */
  [class^="css-"][class*="-control"] input { background-color: transparent !important; }
  /* brand yellow on the page's own black ground; the shared h1 rule would flatten it */
  [class*="SearchArtists__Title"] { color: #ffff64 !important; }

  /* Footer (both React + legacy) */
  [class*="PageFooter-desktop__Container"], [class*="PageFooter"][class*="Container"],
  [class*="PageFooter-shared"], footer, .footer, .page_footer {
    background-color: #0d1117 !important; border-color: #2d333b !important; color: #c4cdd6 !important; }
  [class*="PageFooter"] a, [class*="PageFooterArtistLinks__Link"],
  [class*="PageFooterHotSongLinks__Link"], [class*="PageFooter-desktop__Link"],
  footer a, .footer a { color: #9aa7f0 !important; }
  [class*="PageFooter-desktop__FinePrint"], [class*="PageFooter-desktop__Label"] { color: #8b949e !important; }
  [class*="PageFooterSocial__Slogan"] { color: #e6edf3 !important; }

  /* ---- Image loading placeholders: light-grey skeleton -> dark ---- */
  [class*="SizedImage__Container"], [class*="SizedImage__Image"],
  .clipped_background, .mini_card-thumbnail, .mini_article_card-thumbnail,
  .cover_art, .vertical_album_card-cover_art, [class*="image_with_overlay"] {
    background-color: #1c2128 !important; }

  /* ---- Ad surrounds: dark frame + dark loading slot, don't theme iframe content ---- */
  [class*="SectionLeaderboard__Container"], [class*="ChartHeader-desktop__AdContainer"],
  [class*="LyricsSidebarAd__"], [class*="SongCommentsWithAds__Footer"],
  [id*="ad_"], [class*="dfp"], [class*="Leaderboard"] {
    background-color: #14181d !important; }
  /* Google DFP ad slots have stable ids — darken the empty/loading slot background */
  [id^="div-gpt-ad-"], [id*="google_ads_iframe"], [id$="__container__"], ins.adsbygoogle {
    background-color: #14181d !important; }
  /* a hashed sibling placeholder paints #e9e9e9 while the slot is empty; always the next
     sibling, so target it structurally */
  [id^="div-gpt-ad-"] + div { background-color: #14181d !important; }

  /* OneTrust consent surfaces. Both panels ship white and their copy is MIXED - OneTrust
     paints most of it black with its own !important while the shared typography lifts the rest,
     so lift ALL of it. Its SDK ids are stable across builds. */
  #onetrust-banner-sdk, #onetrust-pc-sdk, #onetrust-pc-sdk .ot-active-menu {
    background-color: #1c2128 !important; }
  #onetrust-pc-sdk .category-menu-switch-handler,
  #onetrust-pc-sdk .ot-pc-footer-logo { background-color: #21262d !important; }
  /* the vendor list is a second view inside the same panel; these two chrome rows keep
     OneTrust's white fill, which the outer-container rule above does not reach. */
  #onetrust-pc-sdk #ot-sel-blk { background-color: #21262d !important; }
  #onetrust-pc-sdk #ot-search-cntr { background-color: #1c2128 !important; }
  /* expanding a vendor row opens a white table whose rows carry no fill of their own */
  #onetrust-pc-sdk .ot-ven-dets { background-color: #21262d !important; }
  /* the vendor-list filter flyout (funnel button) and its pointer are a third view: white
     fill at two-id specificity with a light halo, and the panel-wide ink below lands on it */
  #onetrust-pc-sdk #ot-fltr-cnt {
    background-color: #1c2128 !important; box-shadow: 0 0 12px 2px rgba(0, 0, 0, 0.55) !important; }
  #onetrust-pc-sdk #ot-anchor {
    background-color: #1c2128 !important; box-shadow: -3px -3px 5px -2px rgba(0, 0, 0, 0.55) !important; }
  #onetrust-pc-sdk #ot-filter-list-header {
    color: #9aa7f0 !important; -webkit-text-fill-color: #9aa7f0 !important; }
  /* Apply and Cancel both take the host's black fill; on the dark panel they lose their
     edges and each other. Cancel becomes the outline form. */
  #onetrust-pc-sdk #filter-apply-handler { border-color: #4a525c !important; }
  #onetrust-pc-sdk #filter-cancel-handler {
    background-color: transparent !important; border-color: #4a525c !important; }
  /* the purpose panels' "Object to Legitimate Interests" toggle is OneTrust's one WHITE-filled
     button (#4d4d4d ink and edge), so the panel-wide white button ink below erases its label.
     Its pressed twin (.ot-active-leg-btn) is already a black fill with white ink. */
  #onetrust-pc-sdk .ot-obj-leg-btn-handler.ot-inactive-leg-btn {
    background-color: #21262d !important; border-color: #4a525c !important; }
  #onetrust-banner-sdk, #onetrust-banner-sdk *,
  #onetrust-pc-sdk, #onetrust-pc-sdk * {
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }
  #onetrust-banner-sdk a, #onetrust-pc-sdk a {
    color: #9aa7f0 !important; -webkit-text-fill-color: #9aa7f0 !important; }
  /* every action here is a button: either a solid brand-black fill or a bare text
     button on the panel — white reads on both */
  #onetrust-banner-sdk button, #onetrust-banner-sdk button *,
  #onetrust-pc-sdk button, #onetrust-pc-sdk button * {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }
  /* OneTrust fills it pure WHITE - invisible on the white banner, a white slab swallowing
     its own white label on the dark one */
  #onetrust-banner-sdk #onetrust-pc-btn-handler {
    background-color: transparent !important; }
  /* the selected category is marked ONLY by a 10px left bar and every other item ships that
     bar transparent - the blanket reset paints them alike */
  #onetrust-pc-sdk .category-menu-switch-handler { border-left-color: transparent !important; }
  #onetrust-pc-sdk .ot-active-menu.category-menu-switch-handler {
    border-left-color: #ed4337 !important; }
  /* the OneTrust wordmarks (header + "Powered by" footer) are black raster/SVG logos */
  #onetrust-pc-sdk .ot-pc-logo img, #onetrust-pc-sdk .ot-pc-footer-logo img {
    filter: invert(1) !important; }
  /* OneTrust paints the thumb #c1c1c1 with an explicit ::-webkit-scrollbar-thumb rule, so
     `color-scheme: dark` never gets a say */
  #onetrust-banner-sdk, #onetrust-pc-sdk, #onetrust-pc-sdk .ot-tab-list,
  #onetrust-pc-sdk .ot-pc-scrollbar, #onetrust-pc-sdk .ot-grps-cntr {
    scrollbar-color: #4a525c #1c2128 !important; }
  #onetrust-banner-sdk::-webkit-scrollbar-track,
  #onetrust-pc-sdk ::-webkit-scrollbar-track {
    background: #1c2128 !important; }
  #onetrust-banner-sdk::-webkit-scrollbar-thumb,
  #onetrust-pc-sdk ::-webkit-scrollbar-thumb {
    background: #4a525c !important; }

  /* ---- Misc ---- */
  hr { border-color: #2d333b !important; }
  ::selection { background-color: #ed4337 !important; color: #ffffff !important; }
  /* generic safety net: any element painted pure-white or near-white inline */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"] { background-color: #1c2128 !important; }
}

@-moz-document url-prefix("https://genius.com/amp_iframe_html/") {
/* Chrome fragments, not pages: natively transparent inside ".page_header-header", but
     domain("genius.com") matches in the frame, so the base rule would cut a lighter rectangle
     into the darkened bar. Tracking the header hex here would desync when the header rule
     changes. */
  html, body { background-color: transparent !important; }
}
